"""
NAXIONAI — Built-in persona catalog (Phase 3a)

Ported from neuroworks/server/src/lib/personas.ts's BUILTIN_PERSONAS array
(extracted programmatically from the live objects, not hand-transcribed).
Static reference data — these are NOT DB rows, exactly like
department_templates.py's DEPARTMENT_TEMPLATES. Seeded into the `personas`
table on init_db() (see database.py's Persona model) the same way
ensure_default_user() seeds the operator: insert-if-missing by id, never
overwrite a user's edits to an existing row.

What this does NOT include yet (Phase 3b — needs its own design pass, see
the phased migration plan): the lane-discipline preamble and
personaSystemSuffix() composition logic that actually wires an active
persona into a running task's system prompt. naxionai's LangGraph agent
graph is a fixed-topology graph (manager -> orchestrator -> ...), not a
dynamic persona roster, so "how does hiring Maya change what actually
executes" is an architecture decision, not a data-shape port.
"""

from dataclasses import dataclass, field
from typing import List, Optional


@dataclass
class PersonaDef:
    id: str
    name: str
    role: str
    description: str
    job_description: str
    tone: str
    responsibilities: List[str]
    system_prompt_override: Optional[str] = None
    work_mode: Optional[str] = None       # agent | hybrid | human — absent = agent
    language: Optional[str] = None
    is_builtin: bool = True


